import time

class TokenBucketRateLimiter:
    def __init__(self, capacity: int, refill_rate: float):
        if capacity <= 0:
            raise ValueError("capacity harus > 0")
        if refill_rate <= 0:
            raise ValueError("refill_rate harus > 0")
        self.capacity = float(capacity)
        self.refill_rate = float(refill_rate)
        self.tokens = float(capacity)
        self.last_refill = time.monotonic()
        self.lock = threading.Lock()

    def _refill(self):
        now = time.monotonic()
        elapsed = now - self.last_refill
        if elapsed > 0:
            added = elapsed * self.refill_rate
            self.tokens = min(self.capacity, self.tokens + added)
            self.last_refill = now

    def consume(self, tokens: int = 1) -> bool:
        if tokens <= 0:
            raise ValueError("tokens harus > 0")
        if tokens > self.capacity:
            return False
        with self.lock:
            self._refill()
            if self.tokens >= tokens:
                self.tokens -= tokens
                return True
            return False

    def time_until_next_available(self, tokens: int = 1) -> float:
        if tokens <= 0:
            raise ValueError("tokens harus > 0")
        if tokens > self.capacity:
            return float('inf')
        with self.lock:
            self._refill()
            if self.tokens >= tokens:
                return 0.0
            needed = tokens - self.tokens
            return needed / self.refill_rate

# Contoh pemanggilan
if __name__ == "__main__":
    limiter = TokenBucketRateLimiter(capacity=10, refill_rate=2.0)  # 2 token/detik
    print("consume 5:", limiter.consume(5))  # True
    print("consume 6:", limiter.consume(6))  # False, sisa 5
    print("wait time untuk 6 token:", limiter.time_until_next_available(6))
    time.sleep(0.5)
    print("consume 1 setelah 0.5s:", limiter.consume(1))  # True, refill 1 token
    print("sisa tokens:", limiter.tokens)

    # Uji thread-safe
    limiter2 = TokenBucketRateLimiter(capacity=5, refill_rate=5.0)
    results = []
    def worker():
        results.append(limiter2.consume(1))
    threads = [threading.Thread(target=worker) for _ in range(10)]
    for t in threads: t.start()
    for t in threads: t.join()
    print("thread test - sukses:", sum(results), "gagal:", len(results)-sum(results))
    print("semua tes selesai")
